// Authored, gender-aware adventures. Tokens refer only to the lead, never to other cast.
storyCategories.push(['careers','مهن وأحلام','Jobs & dreams'],['animals','حيوانات وطبيعة','Animals & nature'],['family','أنا وعائلتي','My family & me']);
const careerRoles=[
 ['engineer','engineering','المهندس','المهندسة','Engineer','جسور وأفكار','Bridges & ideas'],
 ['mechanic','mechanic','الميكانيكي','الميكانيكية','Mechanic','أدوات وحلول','Tools & solutions'],
 ['pilot','pilot','الطيّار','الطيّارة','Pilot','طائرات وسماء','Planes & skies'],
 ['police','police','الشرطي','الشرطية','Community officer','أمان ومساعدة','Safety & helping'],
 ['medic','medic','المسعف','المسعفة','Ambulance helper','رفق واستعداد','Care & readiness'],
 ['firefighter','firefighter','بطل الإطفاء','بطلة الإطفاء','Firefighter','وقاية وتعاون','Prevention & teamwork']
];
for(const [id,pack,m,f,en,tag,tagEn] of careerRoles){
 scenePacks[pack]={count:8,rows:2};
 for(const gender of ['male','female']){const girl=gender==='female',givenName=girl?'somoud':'isa';characters.push({id:id+(girl?'-girl':'-boy'),ar:storyCast[givenName].ar+' — '+(girl?f:m),en:storyCast[givenName].en+' — '+en,gender,givenName,group:'careers',sheet:`assets/book/${pack}-adventures.webp`,portrait:girl?1:0,tag:[tag,tagEn],outfit:[girl?f:m,en],world:'forest'});}
}
scenePacks.family={count:8,rows:2};
function genderText(text,gender,name){return String(text).replace(/\{hero\}/g,name).replace(/\[([^\[\]|]+)\|([^\[\]|]+)\]/g,(_,m,f)=>gender==='female'?f:m)}
// Inside these strings, / separates pages so gender tokens can use | safely.
function adventure(meta,ar,en){newAdventure(meta,ar.split(' / ').join('\u001f'),en.split(' / ').join('\u001f'))}
// Use an unambiguous separator; Arabic/English gender alternatives retain their pipes.
function newAdventure(meta,ar,en){const [id,category,lead,pack,titleAr,titleEn,role]=meta,templates={ar:ar.split('\u001f').map(p=>p.trim()),en:en.split('\u001f').map(p=>p.trim())};if(templates.ar.length!==8||templates.en.length!==8)throw Error('New adventure must have eight pages: '+id);const gender=lead==='somoud'?'female':'male',name=storyCast[lead];const s={id,category,lead,pack,ar:genderText(titleAr,gender,name.ar),en:genderText(titleEn,gender,name.en),titleTemplates:{ar:titleAr,en:titleEn},templates,pages:{ar:templates.ar.map(p=>genderText(p,gender,name.ar)),en:templates.en.map(p=>genderText(p,gender,name.en))},sequence:[0,1,2,3,4,5,6,7],character:role?role+(gender==='female'?'-girl':'-boy'):storyCast[lead].character,world:'forest'};storyCatalog.push(s);fictionTopics.push({id:s.id,ar:s.ar,en:s.en});};

adventure(['bridge-builders','careers','somoud','engineering','{hero} والجسر الذي انتظر القطار','{hero} and the bridge waiting for a train','engineer'],
`في ورشة النماذج، [وقف|وقفت] {hero} أمام نهر أزرق من الورق. قطار صغير ينتظر العبور، والجسر لم يكتمل. [قال|قالت]: «لن نترك الركّاب ينتظرون!» / [رسم|رسمت] {hero} خطًّا مستقيمًا بين الضفتين. حين [وضع|وضعت] اللوح، انحنى في المنتصف. ضحك مدرك: «القطار لم يصعد أصلًا!» / أشارت المهندسة إلى صندوق الأشكال: مربعات ومثلثات. «اختبروا ما يحافظ على شكله». [ضغط|ضغطت] {hero} نموذجًا مربعًا برفق، فمال إلى جانب. / ثبّتت المهندسة دعامات مثلثة تحت الجسر. هذه المرّة صمد اللوح. [ابتسم|ابتسمت] {hero}، لكن القطار توقّف عند بدايته. ماذا بقي؟ / [انحنى|انحنت] {hero} إلى مستوى العجلات. طرف السكة أعلى قليلًا من الجسر! لم تكن المشكلة الجديدة في قوّته، بل في الطريق إليه. / عدّل الفريق الارتفاع بمساعدة المهندسة، ثم جرّبوا عربة خفيفة. عبرت ببطء، وتبعتها عربات القطار واحدة واحدة. / [كتب|كتبت] {hero} على بطاقة المعرض: «اختبرنا الشكل، ثم الارتفاع». طلب زائر رؤية النموذج الأول، فأخرجوه بدل إخفائه. / عند إغلاق الورشة، عاد القطار إلى محطّته. [قال|قالت] {hero}: «غدًا سنبني محطة!» أجاب مدرك: «بشرط أن نجد للركّاب مقاعد هذه المرّة».`,
`At the model workshop, {hero} faced a blue paper river. A little train waited for a bridge. “We must not keep its passengers waiting!” [he|she] said. / {hero} drew a straight line between the banks. The first board sagged before the train touched it. Mudrik laughed. “It has not even climbed aboard!” / The engineer offered squares and triangles to test. {hero} gently pressed a square frame. It leaned sideways. Which shape would hold? / With triangular supports, the board stayed firm. {hero} smiled, but the train stopped at the entrance. Another problem! / Looking at wheel height, {hero} spotted the track sitting above the bridge. Strength was solved; the approach was not. / With the engineer, they adjusted the height. A light carriage crossed first, then the little train, one carriage at a time. / Their exhibition card read, “We tested shape, then height.” When a visitor asked about the first model, they proudly showed it. / As the train returned to its station, {hero} planned tomorrow’s platform. “With seats for the passengers this time,” Mudrik added.`);

adventure(['wind-wheel','careers','isa','engineering','{hero} والعجلة التي انتظرت الريح','{hero} and the wheel waiting for wind','engineer'],
`في معرض الابتكارات، [حمل|حملت] {hero} عجلة ورقية. كل العجلات تدور، و[عجلته|عجلتها] ساكنة. «هل نسيت الريح ركننا؟» / [جرّب|جرّبت] {hero} النفخ برفق. اهتزّ طرف واحد ولم تتحرّك العجلة. قرب المحور، كان الورق يلامس الحامل. / ساعدت المشرفة في ترك مسافة صغيرة. دارت العجلة دورة واحدة، ثم توقّفت. صار عندهم نصف جواب فقط. / [راقب|راقبت] {hero} عجلة مجاورة. كانت أطرافها مائلة بالتساوي، بينما طرفان من [عجلته|عجلتها] مسطّحان. / طوى الفريق الأطراف برفق، وثبّتت المشرفة المحور. انتظروا النسيم، لكن الممر أصبح هادئًا تمامًا. / فتح المنظّم نافذة العرض الآمنة. دخل الهواء، وبدأت العجلة تدور أسرع من ابتسامة مدرك التي اتّسعت معها. / [وضع|وضعت] {hero} النموذج بجانب رسمين: قبل التعديل وبعده. صار الزوار يقارنون الشكلين بدل تخمين السر. / في المساء، علّق الأب العجلة قرب نافذة البيت. كلّما دارت، [تذكّر|تذكّرت] {hero} أن الفكرة الجميلة تحتاج تجربة ثانية.`,
`At the invention fair, {hero} held a paper wind wheel. Every other wheel spun. “Did the breeze forget our corner?” / A gentle puff moved one edge, but not the wheel. Paper rubbed against its support beside the axle. / The supervisor made a small gap. One turn, then a stop. They had only half an answer. / {hero} compared a neighbor’s wheel. All its tips leaned evenly; two of [his|her] own were flat. / They folded the tips carefully. The supervisor secured the axle. Now the corridor had no breeze at all! / The organizer opened the safe display window. Air arrived and the wheel spun, just as Mudrik’s smile widened. / {hero} displayed two drawings beside it: before and after. Visitors could compare, rather than guess. / Dad hung the wheel near a window at home. Each turn reminded {hero} that a good idea sometimes needs a second experiment.`);

adventure(['toy-wheel','careers','mudrik','mechanic','{hero} والعجلة التي تقول طق','{hero} and the wheel that clicked','mechanic'],
`كانت سيارة المعرض تصدر صوتًا: طق... طق... ثم تقف. [فتح|فتحت] {hero} دفتر الملاحظات. «[الميكانيكي|الميكانيكية] [يبدأ|تبدأ] [بأذنيه|بأذنيها] أيضًا!» / [دفع|دفعت] {hero} السيارة على الطاولة بإذن المدرّب. الصوت يتكرّر كلّما دارت العجلة الأمامية دورة كاملة. / قال عيسى: «لنبدّل كل العجلات». [هزّ|هزّت] {hero} [رأسه|رأسها]: «لنعرف أوّلًا أيّها يشتكي». رفع المدرّب النموذج لتدور كل عجلة وحدها. / بين العجلة والهيكل علقت قطعة ورق صغيرة. أزالها المدرّب، وعادت السيارة تتحرّك، لكن صوتًا خفيفًا بقي. / [لاحظ|لاحظت] {hero} ملصقًا طويلًا يلمس الأرض من الخلف. ضحك الفريق؛ للسيارة مشكلتان، لا مشكلة واحدة. / قصّ المدرّب طرف الملصق، ثم أعادوا الاختبار من البداية. قطعت السيارة المسار كاملًا دون طقّة. / [رسم|رسمت] {hero} أذنًا وعجلة وورقة في الدفتر. «سمعنا، ثم حدّدنا المكان، ثم جرّبنا». / قبل المغادرة، اختار مدرك اسمًا للسيارة: «الهادئة». وفي طريق البيت، [صار|صارت] {hero} [يستمع|تستمع] إلى أصوات الأشياء بحبّ أكثر.`,
`The exhibition toy car went click, click, then stopped. {hero} opened a notebook. “Mechanics use their ears too!” / With the trainer’s permission, {hero} pushed it along the table. The sound returned once each front-wheel turn. / Isa suggested changing every wheel. “First, which one is complaining?” {hero} asked. The trainer lifted the model to test them separately. / A paper scrap was caught beside a wheel. The trainer removed it. The car moved, but a faint sound remained. / {hero} spotted a long sticker touching the floor at the back. Two problems, not one! / The trainer trimmed the sticker. They restarted their test, and the car completed the course without a click. / {hero} drew an ear, a wheel and paper: “Listen, locate, test.” / Mudrik named the car Quiet One. On the way home, {hero} listened to familiar things with fresh curiosity.`);

adventure(['bicycle-bell','careers','somoud','mechanic','{hero} وجرس الدراجة الخجول','{hero} and the shy bicycle bell','mechanic'],
`في ركن الصيانة المدرسي، [ضغط|ضغطت] {hero} جرس دراجة ثابتة. خرج منه صوت قصير خجول، بينما جرس مدرك يرنّ بوضوح. / [سأل|سألت] {hero} المشرف: «هل ضاع صوته؟» قرّب الجرس ليريهما غطاءه، دون أن يفكّه الأطفال بأنفسهم. / كان شريط زينة يلامس الغطاء. رفعته المشرفة، فعلا الصوت قليلًا، لكنه لم يصبح رنّة كاملة. / [تذكّر|تذكّرت] {hero} الجرس الصغير في البيت؛ يرنّ ما دام لا يمسك أحد بغطائه. هنا كان الغطاء مضغوطًا قرب المقبض. / عدّل المشرف موضع الجرس وثبّته جيدًا، ثم [ضغط|ضغطت] {hero} الرافعة. رنّ الصوت واضحًا حتى التفتت أمينة المكتبة! / «وصل صوتنا أبعد مما نحتاج»، [قال|قالت] {hero} [ضاحكًا|ضاحكةً]. جرّبوا إشارة هادئة تناسب المعرض داخل المدرسة. / علّق الفريق بطاقة: «نترك للجرس مساحة ليهتزّ». وصارت الدراجة الثابتة أكثر ركن يجذب الأسئلة. / في النهاية [استأذن|استأذنت] {hero} ليرنّ الجرس مرة أخيرة. قال مدرك: «لم يعد خجولًا؛ صار يعرف متى يتكلّم».`,
`At the school repair corner, {hero} pressed a bell on a stationary bicycle. A tiny shy sound came out. Mudrik’s bell rang clearly. / “Has its voice vanished?” {hero} asked. The supervisor brought the bell closer for everyone to observe. / A ribbon touched its lid. Moving it helped, but the ring was still short. / {hero} remembered a bell at home: holding the lid stopped its sound. This lid was squeezed against the handle. / The supervisor adjusted and secured it. {hero} pressed the lever. The librarian turned around at the clear ring! / “Further than we needed,” {hero} laughed. They tried a gentle signal suitable for the indoor exhibition. / Their label read, “Leave room for the bell to vibrate.” The stationary bicycle attracted wonderful questions. / {hero} asked for one last ring. “Not shy now,” Mudrik said. “It knows when to speak.”`);

adventure(['pilot-wind','careers','isa','pilot','{hero} وسرّ كيس الريح','{hero} and the windsock secret','pilot'],
`من نافذة مركز الزوّار، [شاهد|شاهدت] {hero} كيسًا برتقاليًّا طويلًا يتحرّك قرب المدرج. «هل يودّع الطائرات؟» / ابتسمت الطيّارة المرشدة: «إنّه يخبرنا عن الريح». [رسم|رسمت] {hero} اتجاهه في دفتر الزيارة. / في جهاز المحاكاة، تغيّر اتجاه الريح على الشاشة. لكن الطائرة الصغيرة بقيت على المسار القديم. بدا الهبوط غريبًا. / [رفع|رفعت] {hero} [يده|يدها]: «نحتاج أن نراجع العلامة الجديدة، لا رسمنا القديم». أوقفت المرشدة المحاكاة لتشرح. / قارنوا العلامات على الشاشة، وعدّلت المرشدة التدريب. الأطفال يختارون الإجابات، وهي وحدها تتحكّم بالجهاز. / وصلت الطائرة الافتراضية إلى مكانها بأمان. [صفّق|صفّقت] {hero}، ثم [نظر|نظرت] إلى الدفتر: تغيّرت الريح مرة أخرى! / أضاف الفريق سهمًا جديدًا بلون مختلف. صار الدفتر يحكي عن شيء يتحرّك، لا عن جواب يبقى صحيحًا دائمًا. / عند الخروج، [لوّح|لوّحت] {hero} للكيس البرتقالي. «عرفت عملك الآن»، [قال|قالت]. وردّت الريح بتحريك ذيله الطويل.`,
`Through the visitor-center window, {hero} spotted an orange windsock near the runway. “Is it waving goodbye to planes?” / The pilot guide smiled. “It tells us about the wind.” {hero} drew its direction. / In the simulator, the wind changed on screen, but the model plane kept its old route. The landing looked strange. / “We need the new sign, not our old drawing,” {hero} said. The guide paused to explain. / They compared the signs. Children chose answers while the guide alone operated the training controls. / The virtual plane reached its place safely. {hero} clapped, then noticed the wind had changed again! / A different-colored arrow went into the notebook. It now showed something changing, not an answer true forever. / On leaving, {hero} waved to the windsock. “I know your job now.” The breeze moved its long tail in reply.`);

adventure(['paper-flight','careers','somoud','pilot','{hero} والطائرة التي اختارت اليسار','{hero} and the plane that turned left','pilot'],
`في قاعة الطيران، [صنع|صنعت] {hero} طائرة ورقية للمعرض. كلّما انطلقت، مالت يسارًا كأنها تعرف سرًّا هناك. / أراد مدرك أن يقذفها بقوة. [قال|قالت] {hero}: «ربما نحتاج النظر إليها قبل أن نطلب منها السرعة». / وضعاها على الطاولة. أحد الجناحين أعلى من الآخر، وطرف الورقة مطوي إلى الداخل. / ساعدت المرشدة في تسوية الطيّة. [جرّب|جرّبت] {hero} إطلاقًا خفيفًا في المسار المخصّص. تحسّن اتجاهها، لكنها بقيت تميل. / هذه المرّة [قارن|قارنت] {hero} الجناحين من الأمام، لا من الأعلى. ظهر اختلاف صغير لم تلتقطه النظرة الأولى. / بعد تعديل المرشدة، طارت الورقة إلى دائرة الهبوط. قفز مدرك فرحًا، ثم جمعها من المسار بعد توقف اللعب. / سمّى الفريق الطائرة «المستقيمة تقريبًا». سألت المرشدة: «لماذا تقريبًا؟» أجابوا: «لأننا ما زلنا نتعلّم». / [حمل|حملت] {hero} الطائرة إلى البيت كأنها تذكرة سفر. وفي الدفتر [رسم|رسمت] جناحين، وتحتَهما عينين تراقبان.`,
`At the aviation exhibition, {hero} made a paper plane. Each flight curved left, as though a secret waited there. / Mudrik wanted a stronger throw. “Perhaps we should look before asking it for speed,” {hero} suggested. / One wing sat higher, and an edge folded inward. They placed it on the table to compare. / The guide helped straighten the fold. A gentle launch in the marked lane improved its route, but not completely. / This time {hero} compared the wings from the front. A small difference had hidden from the view above. / After the guide’s adjustment, the plane reached the landing circle. Mudrik collected it after play stopped. / They named it Almost Straight. “Why almost?” “Because we are still learning!” / {hero} carried the plane home like a travel ticket, then drew two wings with two watchful eyes beneath them.`);

adventure(['crossing-clue','careers','mudrik','police','{hero} وإشارة العبور المختبئة','{hero} and the hidden crossing sign','police'],
`في مدينة المرور المصغّرة، توقّفت كل السيارات اللعبة. كانت الإشارة خضراء، لكن المشاة لا يعرفون أين يعبرون. / [ارتدى|ارتدت] {hero} زيًّا تعليميًّا للزيارة، و[رافق|رافقت] الشرطية المرشدة. «من أين نبدأ السؤال؟» / أشار طفل إلى شريط أبيض خلف صندوق العرض. كان جزءًا من ممرّ المشاة الذي أخفته لافتة كبيرة. / [قال|قالت] {hero}: «إذن المشكلة ليست في الناس». نقل المنظّم اللافتة، فظهر الممر كاملًا، لكن طريقه ينتهي عند عربة. / حرّك المسؤول العربة من المسار. راجعت الشرطية المكان مع الجميع؛ لا يكفي أن نرى بداية الطريق إذا كانت نهايته مغلقة. / عاد المشاة إلى الرصيف، ثم عبروا النموذج حين أشارت المرشدة. انطلقت السيارات اللعبة بعدهم، وعادت المدينة تتحرّك. / [رسم|رسمت] {hero} خريطة صغيرة فيها عينان وسهم. كتب الفريق: «نرى الطريق كاملًا، ونعبر مع الكبير المسؤول». / في طريق البيت، [أمسك|أمسكت] {hero} بيد الأب عند الممر الحقيقي. هذه المرّة بقي زيّ اللعبة في الحقيبة، وبقي التعلّم حاضرًا.`,
`In the model traffic town, every toy car stopped. The light was green, but pedestrians could not find their crossing. / Wearing a learning costume, {hero} joined the police guide. “Where should our questions begin?” / A child pointed behind a display box. White stripes peeked from under a large sign. / “The people are not the problem,” {hero} said. Moving the sign revealed the crossing, but a cart blocked its end. / The organizer cleared the cart. The guide checked the whole route. A visible beginning was not enough with a blocked ending. / Children returned to the model pavement and crossed on the guide’s signal. Then the toy cars moved again. / {hero} drew watchful eyes and an arrow: “See the whole route; cross with your responsible grown-up.” / At a real crossing on the way home, {hero} held Dad’s hand. The costume stayed in the bag; the learning stayed close.`);

adventure(['help-desk','careers','somoud','police','{hero} وبطاقة العائلة الصغيرة','{hero} and the little family card','police'],
`كانت ساحة المعرض مزدحمة بالألوان. في ركن التوعية، سألت الشرطية: «ماذا نفعل إذا ابتعدنا عن أهلنا؟» [فكّر|فكّرت] {hero} جيدًا. / اقترح مدرك الركض في كل اتجاه. قالت الشرطية: «هذا قد يبعدنا أكثر. نبحث عن موظف معروف في نقطة المساعدة». / [وجد|وجدت] {hero} على خريطة المعرض نجمة زرقاء، لكن اللافتة المعلّقة كانت تحمل دائرة. هل تغيّرت نقطة اللقاء؟ / رافقهم الأب إلى الموظف، فاكتشفوا أن الخريطة قديمة. النقطة الجديدة قرب المدخل، وعلامتها دائرة زرقاء. / [طلب|طلبت] {hero} من المنظّم توضيح العلامة. أضاف لافتة كبيرة، بينما اتفقت الأسرة على المكان الجديد معًا. / في تدريب تمثيلي بحضور الأب، [بقي|بقيت] {hero} عند نقطة المساعدة، و[شرح|شرحت] للموظفة ما يحتاجه الفريق. / عادت الأسرة إلى الطاولة، وأعدّ الأب بطاقة تواصل [يحتفظ|تحتفظ] بها [الطفل|الطفلة]. لم يكتبوها على لافتة عامة أو يعطوها لغريب. / عند المغادرة [قال|قالت] {hero}: «حفظت الطريق إلى المساعدة، لا الطريق إلى الخوف». ولوّح مدرك للدائرة الزرقاء.`,
`At the colorful fair, the police guide asked what to do if separated from family. {hero} thought carefully. / Mudrik proposed running everywhere. “That could take us farther away,” said the guide. “Find a known staff member at the help point.” / {hero} saw a blue star on the map, but the sign showed a circle. Had the meeting point changed? / Dad accompanied them to ask staff. The map was old; the new help point was marked with a blue circle near the entrance. / {hero} asked the organizer to clarify the sign. The family agreed on the new place together. / In a pretend practice with Dad present, {hero} stayed at the desk and explained what the group needed. / Dad prepared a contact card for the child to keep. Its details stayed private, away from public signs and strangers. / “I learned the way to help, not the way to fear,” {hero} said. Mudrik waved goodbye to the blue circle.`);

adventure(['teddy-ambulance','careers','isa','medic','{hero} والدب الذي تأخّر عن موعده','{hero} and the bear late for its appointment','medic'],
`في معرض الإسعاف، انتظر دبّ قماشي فوق سيارة لعبة. تأخّر عن موعد العيادة الخيالية، لأن الطريق إلى الطاولة مزدحم بالمكعّبات. / [حمل|حملت] {hero} بطاقة المسعف الصغير. [سأل|سألت] المدرّبة: «هل نسرع فوق المكعّبات؟» ابتسمت: «لنراجع الطريق أولًا». / اقترح مدرك مسارًا قصيرًا، لكنه ضيّق. [قاس|قاست] {hero} عرض السيارة بشريط ورقي، فظهر لماذا لن تعبر. / فتح الفريق مسارًا أوسع بإذن المنظّم، وبقي الدب ينتظر. قالت المدرّبة: «نخبر من ينتظرنا بما تغيّر». / [أوصل|أوصلت] {hero} رسالة إلى موظفة العيادة التمثيلية: الطريق الجديد أطول قليلًا، لكنه واضح ومتاح. / تحرّكت السيارة اللعبة ببطء، ووصل الدب دون أن تنقلب مكعّباته. كانت المدرّبة مسؤولة عن كل أدوات العرض. / [وضع|وضعت] {hero} فوق الطاولة قلبًا ورقيًّا: «المساعدة تبدأ بالانتباه، وطلب الكبير المختص». / في البيت، نام الدب في سريره الصغير في الموعد. همس مدرك: «غدًا سنعلّمه ألا يحجز موعدًا خلف مدينة مكعّبات».`,
`At the ambulance exhibition, a teddy bear waited on a toy vehicle. Its pretend clinic appointment was late: blocks crowded the route. / {hero} wore a junior-helper badge. “Should we rush over them?” “Let us check the route first,” the trainer replied. / Mudrik found a short but narrow path. {hero} measured the toy with a paper strip. It would not fit. / With permission, they opened a wider route. “Tell the people waiting what changed,” the trainer reminded them. / {hero} delivered a message to the pretend clinic desk: a slightly longer, clear route was ready. / The toy traveled slowly without toppling the blocks. The trainer remained responsible for the display equipment. / {hero} placed a paper heart on the desk: “Helping begins with noticing and asking a qualified grown-up.” / At home, teddy reached bed on time. “Tomorrow, no appointments behind a block city,” Mudrik whispered.`);

adventure(['clear-route','careers','somoud','medic','{hero} والطريق إلى القلب الورقي','{hero} and the path to the paper heart','medic'],
`اختفى سهم أحمر من خريطة معرض المساعدة. [بحث|بحثت] {hero} عن الطريق إلى ركن الإسعاف، فإذا بالأسهم تقود إلى ركن الرسم! / [سأل|سألت] الموظفة، فعرفت أن الأطفال نقلوا لوحة أثناء ترتيب المعرض. لم ينتقل الركن، بل انتقلت علامته. / [جمع|جمعت] {hero} مدرك وعيسى، وقارنوا الخريطة بالممرات مع المشرفة. وجدوا علامة ثانية مقلوبة أيضًا. / أراد مدرك رسم أسهم كثيرة في كل مكان. [قال|قالت] {hero}: «نحتاج علامات واضحة، لا متاهة جديدة». / أعاد المنظّم اللوحات إلى أماكنها، وجرّب الفريق الطريق من المدخل. بقي انعطاف واحد لا تظهر عنده الإشارة. / أضاف المسؤول علامة هناك، ووصل زائر جديد إلى الركن دون أن يسأل مرتين. لم تكن سرعة الخطوات هي الحل. / عند طاولة الختام [حصل|حصلت] {hero} على قلب ورقي، وفيه مكان لاسم شخص ساعده الفريق. [كتب|كتبت]: «كل من سأل ولم يستحِ». / [عاد|عادت] {hero} إلى البيت بالقلب والخريطة. وعلّقتهما الأم معًا: قلب يحبّ المساعدة، وعقل يعرف كيف يصل.`,
`A red arrow had vanished from the help exhibition map. Looking for the ambulance corner, {hero} arrived at the art table instead. / A staff member explained: a sign had moved during setup. The corner itself had never moved. / With the supervisor, {hero}, Mudrik and Isa compared the map and corridors. Another sign faced the wrong way. / Mudrik wanted arrows everywhere. “Clear signs, not a new maze,” {hero} suggested. / The organizer restored them. Testing from the entrance revealed one turn with no visible sign. / A new marker helped the next visitor arrive without asking twice. Faster footsteps had not been the answer. / {hero} received a paper heart with room to name someone the team helped. [He|She] wrote, “Everyone who felt brave enough to ask.” / At home, Mum hung the heart beside the map: kindness that wanted to help, and thoughtful directions to reach it.`);

adventure(['exit-map','careers','mudrik','firefighter','{hero} وخريطة الباب الآمن','{hero} and the safe-door map','firefighter'],
`في يوم زيارة الإطفاء، [شاهد|شاهدت] {hero} نموذج بيت صغير. طُلب من الفريق العثور على مسار الخروج في تدريب بلا دخان ولا نار. / [رسم|رسمت] {hero} أقصر خط إلى الباب، لكن قطعة أثاث لعبة كانت تعترضه. قال مدرك: «الخريطة لا ترى الكرسي!» / شرح المدرّب أن الطريق الواضح يحتاج أن يبقى خاليًا. حرّك المنظّم قطعة الأثاث من النموذج، ثم بدأوا من جديد. / عند الباب وجدوا سهمًا يشير إلى درج مغلق في نموذج العرض. هنا [توقّف|توقّفت] {hero}: «نحتاج تأكيدًا، لا تخمينًا». / صحّح المدرّب السهم، وبيّن نقطة التجمع المخصّصة للتدريب. تبع الأطفال تعليماته بهدوء مع أهلهم. / وصل الجميع إلى النقطة نفسها. لم يركض أحد لاستعادة دمية من البيت النموذجي؛ بقيت للمدرّب كي يشرح دوره. / [رسم|رسمت] {hero} بابًا، ومسارًا خاليًا، وعائلة مجتمعة. علّق الفريق الرسم قرب نموذج الشاحنة. / في المساء، [راجع|راجعت] {hero} مع الأهل تعليمات البيت. لم تصبح الغرفة ساحة بطولة؛ صارت الأسرة أكثر استعدادًا وهدوءًا.`,
`On the fire-station open day, {hero} studied a model house. The team would find an exit route in a drill with no smoke or fire. / The shortest line met a toy chair. “The map cannot see furniture!” Mudrik said. / The trainer explained why a clear route must stay clear. The organizer moved the model chair, and they restarted. / An arrow pointed toward a closed model staircase. “We need confirmation, not a guess,” {hero} said. / The trainer corrected it and identified the practice meeting point. Children followed instructions calmly with family. / Everyone reached the same point. No one returned for a toy; the trainer used it to explain the lesson. / {hero} drew a door, a clear path and a gathered family beside the fire-engine model. / At home, {hero} reviewed the household plan with family. The result was preparation and calm, not a dangerous adventure.`);

adventure(['fire-engine','careers','isa','firefighter','{hero} والشاحنة التي لم تستعجل','{hero} and the engine that waited','firefighter'],
`في ساحة الزيارة، لم تتحرّك شاحنة الإطفاء الحقيقية. [سأل|سألت] {hero}: «لماذا يراجع الفريق الأدوات وهي ساكنة؟» / قال رجل الإطفاء: «لكي نكون مستعدين حين نحتاجها». أعطى الأطفال نموذجًا ورقيًّا لشاحنة، وقائمة صور لأدوات العرض. / [طابق|طابقت] {hero} الصور بالأماكن بمساعدة المرشدة. كل شيء موجود، إلا قطعة صغيرة في آخر القائمة. / بحث مدرك تحت الطاولة، ووجد قفاز لعبة. لكن الصورة كانت لقطعة أخرى. [قال|قالت] {hero}: «يشبهها لا يعني أنها هي». / راجعت المرشدة سجلّ العرض؛ القطعة عند ركن الشرح المجاور. لم تكن ضائعة، بل أعيرت دون تحديث البطاقة. / أعادها المسؤول وحدّث القائمة. أكمل الفريق فحص النموذج، بينما بقيت أدوات الشاحنة الحقيقية بيد المختصين. / [حصل|حصلت] {hero} على ملصق خوذة. «هل فزنا بالسرعة؟» سأل مدرك. أجابت المرشدة: «فزتم بالمراجعة الجيدة». / وفي المنزل، [جهّز|جهّزت] {hero} حقيبة المدرسة بقائمة صغيرة. كانت مغامرة اليوم قد علّمت حتى الأقلام كيف تصل في موعدها.`,
`The real fire engine stayed parked on the open day. “Why check its equipment while it waits?” {hero} asked. / “So we are ready when needed,” the firefighter said. Children received a paper model and a picture checklist for display items. / With the guide, {hero} matched pictures and places. One small display piece was missing. / Mudrik found a toy glove, but it did not match. “Similar does not mean the same,” {hero} said. / The guide checked the exhibition record. The piece was at the next table; its loan card had not been updated. / Staff returned it and corrected the list. Children finished their model check; real equipment stayed with professionals. / {hero} received a helmet sticker. “Did we win at speed?” “You won at careful checking,” the guide replied. / That evening, {hero} packed a school bag using a little list. Even the pencils would now arrive on time.`);

adventure(['lamb-bell','animals','somoud','family','{hero} والخروف ذو الجرس الصامت','{hero} and the lamb with the silent bell'],
`في مزرعة العائلة، [عرف|عرفت] {hero} الحمل الصغير من رنّة جرسه. هذا الصباح كان الحمل أمامهم، والجرس صامتًا! / [اقترب|اقتربت] {hero} مع صاحب المزرعة، وبقي الأطفال خارج الحظيرة. هل اختفت حبّة الجرس الصغيرة؟ / قلّب الراعي الجرس برفق، فسمعوا رنّة قصيرة. لم يكن مكسورًا، لكن شريطًا قديمًا علق داخله. / أزال الراعي الشريط، وقفز مدرك فرحًا. ثم لاحظوا أن الحمل لا يزال يبتعد عن وعاء الماء. / [أشار|أشارت] {hero} إلى ظلّ الوعاء: غطاء علف كبير ضيّق الممر. أزاحه الراعي، فعاد الحمل نحو أمّه والماء. / هذه المرّة رنّ الجرس مع كل خطوة. [قال|قالت] {hero}: «كنّا نبحث عن صوت، فوجدنا طريقًا يحتاج أن يُفتح». / أحضر الأب دفتر المزرعة، ورسم الأطفال جرسًا وممرًّا واسعًا. لم يحتاجوا أن يطاردوا الحيوان كي يساعدوه. / قبل الرحيل، [لوّح|لوّحت] {hero} للحمل من بعيد. وصلت رنّته واضحة كأنه يودّعهم بلغته الصغيرة.`,
`At the family farm, {hero} recognized a lamb by its little bell. This morning the lamb was present, but its bell was silent. / With the farmer, {hero} watched from outside the pen. Had the bell’s little clapper vanished? / The farmer gently checked it. A short ring sounded; an old ribbon was caught inside. / Removing the ribbon helped, but the lamb still avoided its water bowl. Another clue remained. / {hero} noticed a feed cover narrowing the path. The farmer moved it, and the lamb returned toward its mother and water. / The bell rang at every step. “We searched for a sound and found a path that needed opening,” {hero} said. / Dad opened the farm notebook. The children drew a bell and a broad path. Helping had not required chasing an animal. / {hero} waved from a distance. The little ring sounded like a goodbye in the lamb’s own language.`);

adventure(['horse-ribbon','animals','isa','family','{hero} وشريط الحصان الأزرق','{hero} and the horse’s blue ribbon'],
`كان الحصان هادئًا في الإسطبل، لكن شريط العرض الأزرق اختفى. [بحث|بحثت] {hero} قرب السرج مع المدرّبة؛ الموعد يقترب. / وجد مدرك شريطًا أخضر، واقترح أن يستبدله. [قال|قالت] {hero}: «لنبحث قبل أن نغيّر علامة الفريق». / على باب غرفة الأدوات بقي طرف خيط أزرق. تبعوه، فوجدوا حقيبة العرض القديمة معلّقة خلف الباب. / داخلها الشريط، لكنه معقود حول فرشاة. ضحكت المدرّبة: «ربطته هنا كي لا أنساه، ثم نسيت المكان!» / وهي تفكّ العقدة، [لاحظ|لاحظت] {hero} أن الحصان يراقب وعاءه الفارغ. تجهيز الزينة ليس كل ما يحتاجه قبل العرض. / تولّت المدرّبة العناية بالحصان ومراجعة راحته، ثم ثبّتت الشريط المناسب. بقي الأطفال معها، ولم يقتربوا وحدهم. / سار الحصان بهدوء في جولة قصيرة يقودها المختص. [لوّح|لوّحت] {hero} للأسرة، بينما الشريط يتمايل كقطعة سماء. / عند العودة، [علّق|علّقت] {hero} بطاقة على الحقيبة: «الزينة هنا؛ والاهتمام بصاحبها أوّلًا».`,
`The horse waited calmly, but its blue show ribbon was missing. {hero} searched with the trainer as the visit approached. / Mudrik found green ribbon. “Let us look before changing our team’s color,” {hero} suggested. / A blue thread caught on the tool-room door. Behind it hung the old show bag. / The ribbon was inside, tied around a brush. “A clever reminder, until I forgot the place,” the trainer laughed. / While she untied it, {hero} noticed the horse watching its empty bowl. Decorations were not its only need. / The trainer checked the horse’s care and comfort, then secured the suitable ribbon. Children stayed with her throughout. / A professional led a calm short circuit. {hero} waved to family as the ribbon fluttered like a little piece of sky. / Afterwards {hero} labeled the bag: “Ribbon here. Care for its wearer first.”`);

adventure(['forest-seeds','animals','mudrik','family','{hero} وخريطة البذور الصغيرة','{hero} and the tiny seed map'],
`في الممرّ الطبيعي، [وجد|وجدت] {hero} ثلاث بذور متشابهة. ظنّ مدرك أنها إشارات إلى كنز بين الأشجار. / قال الدليل: «لننظر من الطريق، دون جمع ما يحتاجه المكان». [رسم|رسمت] {hero} مواضع البذور في الدفتر. / عند المنعطف، ظهرت بذرة أخرى تحت شجرة مختلفة. هل غيّرت الأشجار أماكنها في الليل؟ / رفعت نسمة خفيفة بذرة جافّة أمامهم. [راقب|راقبت] {hero} شكلها، [فرأى|فرأت] جناحًا ورقيًّا يدور وهي تهبط. / أوضح الدليل أن الريح قد تحمل بعض البذور. لم تكن الخريطة طريق كنز، بل أثر رحلة نبات صغير. / [أضاف|أضافت] {hero} أسهم الهواء إلى الرسم. وفي مكان ظليل رأوا بادرة جديدة، فوقفوا يتأملونها دون لمسها. / استراحوا في الموضع المخصّص، وجمعوا نفاياتهم. «الكنز هنا أصلًا»، قال مدرك مشيرًا إلى الأشجار. / في البيت، [فتح|فتحت] {hero} الدفتر قرب النافذة. لم يحمل من الغابة إلا حكاية، وخريطة تعرف كيف تترك الأشياء في مكانها.`,
`On the nature trail, {hero} spotted three similar seeds. Mudrik thought they marked a treasure route. / “Observe from the path; leave what the place needs,” the guide said. {hero} drew their locations. / Another seed lay under a different tree. Had the trees moved in the night? / A breeze lifted a dry seed nearby. {hero} watched its paper-like wing turn as it landed. / Some seeds travel with wind, the guide explained. Their map recorded a plant’s journey, not buried treasure. / {hero} added air arrows. In a shaded spot, they admired a new seedling without touching it. / At the rest area they collected their own litter. “The treasure is already here,” Mudrik said, pointing at the trees. / At home, {hero} opened the notebook: a forest story and a map that knew how to leave things in place.`);

adventure(['dad-kite','family','isa','family','{hero} وأبي… والطائرة التي انتظرتنا','{hero}, Dad and the kite that waited'],
`[جهّز|جهّزت] {hero} الطائرة الورقية منذ الصباح، لكن الأب تأخّر في عمله. بدت الخيوط أطول من وقت الانتظار. / حين عاد الأب، [قال|قالت] {hero}: «ظننت أنك نسيت». جلس [بجانبه|بجانبها] وقال: «لم أنسَ، لكنني تأخّرت. لنجد وقتنا معًا». / في الحديقة المفتوحة، ارتفعت الطائرة قليلًا ثم دارت نحو الأرض. شدّ الأب الخيط، وبقي السرّ كما هو. / [فحص|فحصت] {hero} الذيل؛ عقدة صغيرة جمعت شرائطه. «ربما الطائرة أيضًا تنتظر أن نسمعها». / فكّا العقدة على المقعد بعيدًا عن الطريق والأسلاك. راجعا الريح، ثم اختارا موضعًا مناسبًا معًا. / ركضت الطائرة في الهواء، لا أقدامهما في كل اتجاه. أمسك الأب بالخيط، و[راقب|راقبت] {hero} الذيل ينساب أخيرًا. / قال الأب: «شكرًا لأنك أخبرتني بما شعرت». [ابتسم|ابتسمت] {hero}: «وأنا [سعيد|سعيدة] لأننا لم نترك العقدة تكبر». / عادا قبل الغروب ومعهما الطائرة وصورة صغيرة. خلف الصورة كتبا موعدًا جديدًا؛ ليس وعدًا بيوم كامل، بل وقت يعرفانه معًا.`,
`{hero} prepared the kite early, but Dad’s work ran late. Its string seemed longer than the wait. / “I thought you forgot,” {hero} said when he arrived. Dad sat close. “I did not forget, but I was late. Let us find our time together.” / At the open park, the kite rose, twisted and fell. Pulling harder did not solve it. / {hero} spotted a knot tying its tail ribbons together. “Perhaps it is waiting for us to listen too.” / They untied it on a bench, away from roads and wires, then checked the breeze and their safe flying spot. / Dad held the string as {hero} watched the tail flow freely. The kite finally found the sky. / “Thank you for telling me how you felt,” Dad said. “I am glad we did not let the knot grow,” {hero} replied. / They returned with a kite and a photo. On its back they wrote their next shared time: small, clear and theirs.`);

adventure(['mum-recipe','family','somoud','family','{hero} وأمي… وسرّ الملعقة الصغيرة','{hero}, Mum and the little spoon secret'],
`في يوم خبز العائلة، [أراد|أرادت] {hero} صنع مفاجأة للأم. لكن صفحة الوصفة امتلأت بملعقة كبيرة وملعقة صغيرة؛ أيّهما تبدأ الحكاية؟ / دخلت الأم فوجدت الطحين ينتظر في وعائه. [قال|قالت] {hero}: «أردتها مفاجأة وحدي». ابتسمت: «يمكننا أن نصنع المفاجأة معًا». / قرأت الأم المقادير، و[رتّب|رتّبت] {hero} الأدوات على الطاولة. لم يكن الأمر سباقًا، ولا مكانًا للملاعق المتشابهة دون انتباه. / حين جاء دور الملعقة الصغيرة، لم يجدوها. بحث مدرك تحت المنشفة، ووجد ملعقة لعبة تكاد تشبهها. / [قارن|قارنت] {hero} الملعقتين مع الأم. إحداهما للّعب، والأخرى للقياس. وظهر المقياس الحقيقي داخل كوب نظيف. / تولّت الأم الفرن والأدوات الساخنة، بينما زيّن الأطفال البطاقات. انتشرت رائحة الخبز، وصار للانتظار طعم جميل. / [قدّم|قدّمت] {hero} أوّل قطعة للأم. على بطاقتها: «مفاجأتنا». لم تعد الكلمة الصغيرة «معًا» تفسد السرّ؛ كانت أجمل ما فيه. / في دفتر الوصفات، [رسم|رسمت] {hero} ملعقتين وقلبًا. سألت الأم: «ما اسم الوصفة؟» فكان الجواب: «وقت لنا».`,
`On family baking day, {hero} planned a surprise for Mum. The recipe showed a big spoon and a little one. Which began the story? / Mum found flour waiting in its bowl. “I wanted to surprise you alone.” “We can make the surprise together,” she smiled. / Mum read the recipe while {hero} arranged tools. It was no race, and similar spoons needed careful attention. / The measuring spoon vanished. Mudrik found a toy spoon beneath a cloth, almost the right shape. / {hero} compared them with Mum. One was for play, one for measuring. The real measure waited inside a clean cup. / Mum handled the oven and hot tools; children decorated cards. The warm smell made waiting wonderful. / {hero} offered the first piece to Mum with a card reading Our Surprise. Together had become its loveliest secret. / In the recipe notebook, {hero} drew two spoons and a heart. Mum asked its title. “Time for us.”`);

adventure(['family-lantern','family','mudrik','family','{hero} وأهلي… وفانوس لا يضيء وحده','{hero}, family and the lantern that needed everyone'],
`قبل جلسة الحكايات في الفناء، اختفى الفانوس المفضّل. [رفع|رفعت] {hero} غطاء السلة، ولم [يجد|تجد] إلا وسائد صغيرة. / قالت الأم: «لنقسم البحث، ونعود إلى هنا بعد قليل». فتّش الأب قرب الرف، وبحث الأطفال في أماكنهم المعتادة. / عاد مدرك بخيط زينة، وعادت صمود بصورة قديمة للفانوس. [لاحظ|لاحظت] {hero} في الصورة مقبضًا أخضر لم يتذكّره أحد. / [سأل|سألت] {hero} الأب عن المقبض. قال: «أصلحته أمس، ووضعته مع الأدوات بدل الرف!» ذهب ليحضره، فبقي نصف اللغز. / كان الفانوس بلا بطاريته القابلة للشحن؛ وضعتها الأم في مكان الشحن المخصّص. «كلّ واحد عرف قطعة من الحكاية»، [قال|قالت] {hero}. / تولّى الأب تركيبها وتشغيل الفانوس. رتّبت الأم المكان، وجمع الأطفال الوسائد بعيدًا عن الممر. / أضاء الفناء أخيرًا. [جلس|جلست] {hero} وسط الأهل، و[اختار|اختارت] حكاية تبدأ بأشياء ضاعت، وتنتهي بأشخاص وجدوا بعضهم. / وقبل النوم، اتفقت الأسرة على رفّ واضح للفانوس. أمّا أوّل جلسة تحت نوره فسمّوها: «المرة التي أضأناها جميعًا».`,
`Before courtyard story time, the favorite lantern vanished. {hero} lifted a basket lid and found only little cushions. / “Search in teams and meet here again,” Mum suggested. Dad checked the shelf; children checked familiar places. / Mudrik returned with string; Somoud brought an old photo. {hero} noticed a green handle no one remembered. / Dad recalled repairing it and leaving it with his tools. He fetched it, but only half the mystery was solved. / Its rechargeable battery was at Mum’s charging station. “Each person knew a piece of the story,” {hero} said. / Dad fitted and switched it on. Mum arranged the space while children kept cushions clear of the path. / The courtyard glowed. Seated among family, {hero} chose a tale of missing things and people finding one another. / They agreed on one clear shelf for the lantern. Their first evening beneath it became The Night We All Brought the Light.`);
